:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-cream-tile: #f8f5ed;
  --color-fog-wash: #0000000a;
  --color-jet-ink: #000000;
  --color-pewter-caption: #707070;
  --color-ash-hairline: #0000000f;
  --color-mint-signal: #6ece9d;
  --color-mint-halo: #6ece9d59;
  --color-sunbeam-accent: #ffda6e;

  /* Typography — Font Families */
  --font-dm-sans: "DM Sans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 14px;
  --leading-small: 1.5;
  --tracking-small: 0px;
  --text-caption: 14px;
  --leading-caption: 1.5;
  --tracking-caption: 4px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: 0px;
  --text-subheading: 20px;
  --leading-subheading: 1.5;
  --tracking-subheading: 0px;
  --text-heading-sm: 24px;
  --leading-heading-sm: 1.25;
  --tracking-heading-sm: 0px;
  --text-heading: 28px;
  --leading-heading: 1.25;
  --tracking-heading: 0px;
  --text-heading-lg: 64px;
  --leading-heading-lg: 1.25;
  --tracking-heading-lg: -1px;
  --text-display: 96px;
  --leading-display: 1.25;
  --tracking-display: -2px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-128: 128px;
  --spacing-192: 192px;

  /* Layout */
  --layout-max-width: 1200px;
  --layout-text-width: 768px;
  --layout-frame-width: 1888px;
  --layout-section-gap: 192px;
  --layout-card-padding: 48px;
  --layout-element-gap: 32px;
  --layout-nav-height: 88px;

  /* Border Radius */
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 20px;
  --radius-2xl: 24px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-cards: 24px;
  --radius-sections: 24px 24px 0px 0px;
  --radius-pills: 20px;
  --radius-inner-tiles: 16px;
  --radius-buttons: 12px;
  --radius-images: 12px;
  --radius-nav: 6px;
  --radius-inputs: 6px;
  --radius-tags: 6px;
  --radius-small-elements: 6px;
  --radius-avatars: 100%;

  /* Shadows */
  --shadow-subtle: rgba(0, 0, 0, 0.06) 0px 0px 0px 1px inset;
  --shadow-sm: rgb(110, 206, 157) 0px 0px 0px 2px;
  --shadow-md: rgba(110, 206, 157, 0.35) 0px 0px 0px 0px;
  --shadow-lg: rgba(0, 0, 0, 0.06) 0px -1px 0px 0px, rgba(110, 206, 157, 0.35) 0px -40px 120px -40px;

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-fog-wash: #0000000a;
  --surface-cream-tile: #f8f5ed;
}

